287:             serde_json::from_str(&finalize_body).map_err(|source| OpenAiFileError::Decode {
288:                 url: finalize_url.clone(),
289:                 source,
290:             })?;
291: 
292:         match finalize_payload.status.as_str() {
293:             "success" => {
294:                 let file_size_bytes = finalize_payload.file_size_bytes.unwrap_or(file_size_bytes);
295:                 return Ok(UploadedOpenAiFile {
296:                     file_id: create_payload.file_id.clone(),
297:                     uri: openai_file_uri(&create_payload.file_id),
298:                     download_url: finalize_payload.download_url.ok_or_else(|| {
299:                         OpenAiFileError::UploadFailed {
300:                             file_id: create_payload.file_id.clone(),
301:                             message: "missing download_url".to_string(),
302:                         }
303:                     })?,
304:                     file_name: finalize_payload.file_name.unwrap_or(file_name),
305:                     file_size_bytes,
306:                     mime_type: finalize_payload.mime_type,
307:                 });
308:             }
309:             "retry" => {
310:                 if finalize_started_at.elapsed() >= OPENAI_FILE_FINALIZE_TIMEOUT {
311:                     return Err(OpenAiFileError::UploadNotReady {
312:                         file_id: create_payload.file_id,
313:                     });
314:                 }
315:                 tokio::time::sleep(OPENAI_FILE_FINALIZE_RETRY_DELAY).await;
316:             }
317:             _ => {
318:                 return Err(OpenAiFileError::UploadFailed {
319:                     file_id: create_payload.file_id,
320:                     message: finalize_payload
321:                         .error_message
322:                         .unwrap_or_else(|| "upload finalization returned an error".to_string()),
323:                 });
324:             }
325:         }
326:     }
