134:     ) -> Result<RealtimeCallResponse, ApiError> {
135:         trace!(target: "codex_api::realtime_websocket::wire", "realtime call request SDP: {sdp}");
136:         // WebRTC can begin inference as soon as the peer connection comes up, so the initial
137:         // session payload is sent with call creation. Legacy sidebands still send session.update
138:         // after joining; Frameless sidebands attach to the session that is already running.
139:         validate_avas_session_config(&session_config)?;
140:         let event_parser = session_config.event_parser;
141:         let path = self.path_for_session(event_parser);
142:         let mut session = realtime_session_json(session_config)?;
143:         if let Some(session) = session.as_object_mut() {
144:             session.remove("id");
145:         }
146:         // TODO(aibrahim): Align the SIWC route with the API multipart shape and remove this branch.
147:         if self.uses_backend_request_shape() {
148:             let body = to_value(BackendRealtimeCallRequest {
149:                 sdp: &sdp,
150:                 session: &session,
151:             })
152:             .map_err(|err| ApiError::Stream(format!("failed to encode realtime call: {err}")))?;
153:             let resp = self
154:                 .session
155:                 .execute_with(Method::POST, path, extra_headers, Some(body), |request| {
156:                     configure_realtime_call_request(
157:                         request,
158:                         event_parser,
159:                         /*uses_backend_request_shape*/ true,
160:                     )
161:                 })
162:                 .await?;
163:             let sdp = decode_sdp_response(resp.body.as_ref())?;
164:             let call_id = decode_call_id_from_location(&resp.headers)?;
165:             return Ok(RealtimeCallResponse { sdp, call_id });
166:         }
167: 
168:         let session = to_string(&session).map_err(|err| ApiError::InvalidRequest {
169:             message: err.to_string(),
170:         })?;
171:         let mut body = Vec::new();
172:         body.extend_from_slice(format!("--{MULTIPART_BOUNDARY}\r\n").as_bytes());
173:         body.extend_from_slice(b"Content-Disposition: form-data; name=\"sdp\"\r\n");
174:         body.extend_from_slice(b"Content-Type: application/sdp\r\n\r\n");
175:         body.extend_from_slice(sdp.as_bytes());
176:         body.extend_from_slice(b"\r\n");
177:         body.extend_from_slice(format!("--{MULTIPART_BOUNDARY}\r\n").as_bytes());
178:         body.extend_from_slice(b"Content-Disposition: form-data; name=\"session\"\r\n");
179:         body.extend_from_slice(b"Content-Type: application/json\r\n\r\n");
180:         body.extend_from_slice(session.as_bytes());
181:         body.extend_from_slice(b"\r\n");
182:         body.extend_from_slice(format!("--{MULTIPART_BOUNDARY}--\r\n").as_bytes());
183: 
184:         let resp = self
185:             .session
186:             .execute_with(
187:                 Method::POST,
188:                 path,
189:                 extra_headers,
190:                 /*body*/ None,
191:                 |req| {
192:                     configure_realtime_call_request(
193:                         req,
194:                         event_parser,
195:                         /*uses_backend_request_shape*/ false,
196:                     );
197:                     req.headers.insert(
198:                         CONTENT_TYPE,
199:                         HeaderValue::from_static(MULTIPART_CONTENT_TYPE),
200:                     );
201:                     req.body = Some(RequestBody::Raw(Bytes::from(body.clone())));
202:                 },
203:             )
204:             .await?;
205: 
206:         let sdp = decode_sdp_response(resp.body.as_ref())?;
207:         let call_id = decode_call_id_from_location(&resp.headers)?;
208: 
209:         Ok(RealtimeCallResponse { sdp, call_id })
210:     }
211: }
