213: fn configure_realtime_call_request(
214:     request: &mut Request,
215:     event_parser: RealtimeEventParser,
216:     uses_backend_request_shape: bool,
217: ) {
218:     if event_parser == RealtimeEventParser::V1
219:         || (uses_backend_request_shape && event_parser == RealtimeEventParser::FramelessBidi)
220:     {
221:         append_query_pair(&mut request.url, "intent", "quicksilver");
222:         append_query_pair(&mut request.url, "architecture", "avas");
223:     }
224: }
225: 
226: fn validate_avas_session_config(session_config: &RealtimeSessionConfig) -> Result<(), ApiError> {
227:     if session_config.event_parser == RealtimeEventParser::RealtimeV2 {
228:         return Err(ApiError::InvalidRequest {
229:             message: "AVAS realtime calls require realtime v1 or v3".to_string(),
230:         });
231:     }
232:     Ok(())
233: }
234: 
235: fn append_query_pair(url: &mut String, key: &str, value: &str) {
236:     if url.contains('?') {
237:         url.push('&');
238:     } else {
239:         url.push('?');
240:     }
241:     url.push_str(key);
242:     url.push('=');
243:     url.push_str(value);
244: }
245: 
246: fn realtime_session_json(session_config: RealtimeSessionConfig) -> Result<Value, ApiError> {
247:     session_update_session_json(session_config)
248:         .map_err(|err| ApiError::Stream(format!("failed to encode realtime call session: {err}")))
249: }
250: 
251: fn decode_sdp_response(body: &[u8]) -> Result<String, ApiError> {
252:     String::from_utf8(body.to_vec()).map_err(|err| {
253:         ApiError::Stream(format!(
254:             "failed to decode realtime call SDP response: {err}"
255:         ))
256:     })
257: }
258: 
259: fn decode_call_id_from_location(headers: &HeaderMap) -> Result<String, ApiError> {
260:     let location = headers
261:         .get(LOCATION)
262:         .ok_or_else(|| ApiError::Stream("realtime call response missing Location".to_string()))?
263:         .to_str()
264:         .map_err(|err| ApiError::Stream(format!("invalid realtime call Location: {err}")))?;
265:     trace!("realtime call Location: {location}");
266: 
267:     location
268:         .split('?')
269:         .next()
270:         .unwrap_or(location)
271:         .rsplit('/')
272:         .find(|segment| is_realtime_call_id_segment(segment))
273:         .map(str::to_string)
274:         .ok_or_else(|| {
275:             ApiError::Stream(format!(
276:                 "realtime call Location does not contain a call id: {location}"
277:             ))
278:         })
279: }
280: 
281: fn is_realtime_call_id_segment(segment: &str) -> bool {
282:     if segment.starts_with("rtc_") && segment.len() > "rtc_".len() {
283:         return true;
284:     }
285: 
286:     if segment.len() != 36 {
287:         return false;
288:     }
289: 
290:     segment.char_indices().all(|(index, ch)| match index {
291:         8 | 13 | 18 | 23 => ch == '-',
292:         _ => ch.is_ascii_hexdigit(),
293:     })
294: }
