458:             RealtimeOutboundMessage::SessionContextAppend { channel, content } => {
459:                 if let Some(content) = content.first() {
460:                     for chunk in context_append_chunks(&content.text) {
461:                         self.send_json_frame(&frameless_session_context_append_message(
462:                             chunk, *channel,
463:                         ))
464:                         .await?;
465:                     }
466:                     return Ok(());
467:                 }
468:             }
469:             _ => {}
470:         }
471:         self.send_json_frame(message).await
472:     }
473: 
474:     async fn send_json_frame(&self, message: &RealtimeOutboundMessage) -> Result<(), ApiError> {
475:         let payload = serde_json::to_string(message)
476:             .map_err(|err| ApiError::Stream(format!("failed to encode realtime request: {err}")))?;
477:         debug!(?message, "realtime websocket request");
478:         self.send_payload(payload).await
479:     }
480: 
481:     pub async fn send_payload(&self, payload: String) -> Result<(), ApiError> {
482:         if self.is_closed.load(Ordering::SeqCst) {
483:             return Err(ApiError::Stream(
484:                 "realtime websocket connection is closed".to_string(),
485:             ));
486:         }
487: 
488:         trace!(target: REALTIME_WIRE_LOG_TARGET, "realtime websocket request: {payload}");
489:         self.stream
490:             .send(Message::Text(payload.into()))
491:             .await
492:             .map_err(|err| ApiError::Stream(format!("failed to send realtime request: {err}")))?;
493:         Ok(())
494:     }
495: }
